  $('#documents').innerHTML=shown.map(d=>`<article class="doc-card ${librarySelected.has(d.id)?'library-selected':''}"><label class="library-checkbox" ${librarySelection?'':'hidden'}><input type="checkbox" data-doc-select="${esc(d.id)}" aria-label="${esc(t('تحديد المستند')+' '+d.name)}" ${librarySelected.has(d.id)?'checked':''}></label><div class="doc-cover" data-open="${esc(d.id)}" role="button" tabindex="0" aria-label="فتح ${esc(d.name)}">${d.pages[0]?`<img data-preview-key="${esc(previewKey(d,d.pages[0]))}" alt="معاينة أول صفحة" loading="lazy" decoding="async">`:`<div class="blank-doc">${icon('documents')}</div>`}<span class="doc-page-count">${t('{n} صفحات',{n:d.pages.length})}</span></div><div class="doc-info"><h3 data-open="${esc(d.id)}" role="button" tabindex="0">${esc(d.name)}</h3><p>${new Date(d.updated).toLocaleDateString(getLanguage())} ${d.folder?'· '+esc(d.folder):''}</p>${matches.get(d.id).page?`<button class="search-match" data-search-page="${esc(matches.get(d.id).page)}" data-search-doc="${esc(d.id)}"><small>${t('صفحة {n}',{n:matches.get(d.id).pageNumber})}</small><span data-user-content>${esc(matches.get(d.id).snippet)}</span></button>`:''}<div class="doc-actions"><button class="open-doc" data-open="${esc(d.id)}">فتح ${icon('arrow')}</button><button data-fav="${esc(d.id)}" class="icon-btn ${d.favorite?'favorite':''}" aria-label="تبديل المفضلة" aria-pressed="${!!d.favorite}">${icon('star')}</button><details class="action-menu"><summary aria-label="خيارات المستند">${icon('more')}</summary><div class="menu-panel"><button data-folder-move="${esc(d.id)}">${icon('folder')}<span>نقل إلى مجلد</span></button><button data-copy="${esc(d.id)}">${icon('copy')}<span>نسخ</span></button><button data-trash="${esc(d.id)}" class="${d.trashed?'':'danger'}">${icon(d.trashed?'restore':'trash')}<span>${d.trashed?'استعادة':'للسلة'}</span></button>${d.trashed?`<button data-purge="${esc(d.id)}" class="danger">${icon('trash')}<span>حذف نهائي</span></button>`:''}</div></details></div></div></article>`).join('');
  $('#empty').hidden=shown.length>0;thumbnails.attach($('#documents'),new Map(shown.filter(d=>d.pages[0]).map(d=>[previewKey(d,d.pages[0]),d.pages[0].blob])));updateProcessingIndicators();updateLibrarySelection();
