 $('#google-config-save').onclick=()=>{const value=$('#oauth-client').value.trim();if(!value.endsWith('.apps.googleusercontent.com'))return toast('معرّف Google غير صالح');localStorage.setItem('waraqa-oauth-client',value);settings();};
 if(clientId)Drive.googleScript().then(()=>{if($('#google-connect')){$('#google-connect').disabled=false;$('#drive-status').textContent=Drive.connected()?'الحساب مربوط؛ يمكنك المزامنة.':'جاهز للربط بحساب Google.';}}).catch(e=>{if($('#drive-status'))$('#drive-status').textContent=e.message;});
