function mergeDocuments(){const records=docs.filter(d=>!d.trashed&&!d.deleted);modal('جمع مستندات في مستند واحد',`<p class="hint">هاي العملية تجمع الصفحات بالتتابع. لإنشاء صفحة واحدة من صفحتين، افتح مستنداً وحدد الصفحتين.</p>${records.map(d=>`<div class="form-row"><label><input class="merge-check" type="checkbox" value="${esc(d.id)}"> ${esc(d.name)} — ${d.pages.length} صفحات</label></div>`).join('')}`,[button('إنشاء المستند',()=>{const ids=[...document.querySelectorAll('.merge-check:checked')].map(e=>e.value);if(ids.length<2)return toast('حدد مستندين على الأقل');const pages=ids.flatMap(x=>docs.find(d=>d.id===x).pages).map(p=>({...p,id:Core.id()}));if(pages.length>80)return toast('حد المستند 80 صفحة');closeModal();run('دمج المستندات…',async()=>{const d=await persist({...newDoc('مستند مدمج'),pages});current=d.id;});},true)]);}
function extractPages(){const d=doc(),pages=d.pages.filter(p=>selected.has(p.id)).map(p=>({...p,id:Core.id()}));run('استخراج الصفحات…',async()=>{const result=await persist({...newDoc(d.name+' — صفحات مستخرجة'),pages,folder:d.folder});current=result.id;selected.clear();toast('تم إنشاء مستند جديد، الأصل محفوظ');});}
async function restoreBackup(file){if(file.size>80*1024*1024)return toast('النسخة أكبر من الحد المدعوم: 80 ميغابايت');run('استعادة النسخة…',async()=>{let backup=JSON.parse(await file.text());if(backup.app==='waraqa-encrypted'){const password=prompt('كلمة مرور النسخة الاحتياطية:');if(password===null)return;backup=await decryptBackup(backup,password);}if(backup.app!=='waraqa'||backup.schema!==1||!Array.isArray(backup.documents)||backup.documents.length>500)throw Error('ملف النسخة غير مدعوم');const decoded=[];for(const value of backup.documents)decoded.push(await decodeDoc(value));for(let d of decoded){const existing=docs.find(x=>x.id===d.id);if(existing?.rev===d.rev)continue;if(existing)d={...d,id:Core.id(),name:d.name+' (نسخة مستعادة)',rev:Core.id(),ancestors:[]};await persist(d,false);}await setUserPreference('folders',cleanFolders([...knownFolders(),...cleanFolders(backup.folders)]));toast('تمت الاستعادة بدون استبدال مستنداتك');});}
