 const strip=$('#processing-strip');if(strip){strip.hidden=sessionLocked||!job;const progress=$('#processing-progress');if(job){$('#processing-label').textContent=jobLabel(job)+' · '+t('صفحة {n}',{n:Math.min(job.pages.length,(job.completed||0)+1)})+'/'+job.pages.length;progress.value=job.progress||0;}}
 if($('#processing-open'))$('#processing-open').hidden=sessionLocked;if($('#processing-count'))$('#processing-count').textContent=pending.length||'';
 for(const card of $('#documents').children){const id=card.querySelector('[data-open]')?.dataset.open;if(!id)continue;let badge=card.querySelector('.doc-processing');if(!badge){badge=document.createElement('div');badge.className='doc-processing';card.querySelector('.doc-info')?.prepend(badge);}const task=pending.find(j=>j.documentId===id);badge.hidden=!task;badge.textContent=task?jobLabel(task):'';}
