function processingDialog(){modal('مهام المعالجة','<p class="hint">يمكنك متابعة استخدام ورقة أثناء استخراج النص. المهام المحفوظة تستأنف عند فتح التطبيق؛ الصفحات المكتملة تبقى محفوظة عند الإلغاء.</p><div id="processing-list"></div><p id="processing-empty" class="hint">لا توجد مهام حالياً</p>',[button('متابعة التصفح',closeModal)]);$('#modal-body').dataset.jobPanel='true';renderJobRows();}
